#include <iostream>
#include <string>

using namespace std;

int main() {
    string s;
    cin >> s;
    int equal = 0;
    for (int i = 1; i < (int)s.size(); i++) {
        if (s[i] == s[i - 1]) {
            equal++;
        }
    }
    cout << equal << '\n';
}
